#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    int M;
    cin >> N;
    cin >> M;

    vector<int> T(M);
    for (int i = 0; i < M; ++i) {
        cin >> T[i];
    }

    const int LIMIT = 10000;
    int printed = 0;

    for (long long j = 1; printed < LIMIT; ++j) {
        long long pos = j;
        bool ok = true;

        for (int i = M - 1; i >= 0; --i) {
            pos += (pos - 1) / (T[i] - 1);
            if (pos > N) {
                ok = false;
                break;
            }
        }

        if (!ok) break;

        cout << pos << '\n';
        ++printed;
    }

    return 0;
}
